import codecs, hashlib, json, sys, unicodedata

def error(exc):
    if isinstance(exc, UnicodeError) and hasattr(exc, 'encoding'):
        obj = list(exc.object) if isinstance(exc.object, bytes) else list(map(ord, exc.object))
        return [type(exc).__name__, exc.encoding, obj, exc.start, exc.end, exc.reason]
    return [type(exc).__name__, str(exc)]

def digest(rows):
    h=hashlib.sha256();count=0
    for row in rows:
        h.update((json.dumps(row,ensure_ascii=True,separators=(',',':'))+'\n').encode());count+=1
    return {'count':count,'sha256':h.hexdigest()}

def setters():
    encoder=codecs.getincrementalencoder('gbk')()
    initial=int.from_bytes(bytes([1,90,0x42,0x13])+bytes(5),'little')
    inputs=[bytes([a,b]) for a in range(256) for b in range(256)]
    inputs += [bytes.fromhex(s) for s in ['eda080','edbfbf','f0908080','f48fbfbf','f4908080','e08080','c0af','f0808080','e282','f09f98','0000000000000000']]
    states=[int.from_bytes(bytes([len(b)])+b+bytes.fromhex('123456789abcdef0'),'little') for b in inputs]
    states += [-1,1<<136,(1<<136)-1,9,255]
    for s in states:
        encoder.setstate(initial)
        try: encoder.setstate(s); result=['ok']
        except BaseException as exc: result=error(exc)
        yield [str(s),result,str(encoder.getstate())]

def hz_modes():
    for mode in range(256):
      for original in [b'',b'~',b'V']:
       for data in [b'',b'A',b'VP',b'~}',b'~{',b'~~',b'~\n',b'\xff',b'V\xff',b'~}A']:
        for final in [False,True]:
         d=codecs.getincrementaldecoder('hz')()
         d.setstate((original,0x123400|mode))
         try: result=['ok',list(map(ord,d.decode(data,final)))]
         except BaseException as exc: result=error(exc)
         state=d.getstate()
         d.reset()
         reset=d.getstate()
         yield [mode,list(original),list(data),final,result,[list(state[0]),str(state[1])],[list(reset[0]),str(reset[1])]]

print(json.dumps({'version':sys.version,'unicode':unicodedata.unidata_version,'encoder_setters':digest(setters()),'hz_modes':digest(hz_modes())},indent=2))

